exercises.starter_code:
SELECT nom, categorie, prix FROM produits
WHERE prix > (SELECT AVG(prix) FROM produits)
ORDER BY categorie, nom;

exercises.solution:
SELECT p.nom, p.categorie, p.prix FROM produits AS p
WHERE p.prix > (SELECT AVG(p2.prix) FROM produits AS p2 WHERE p2.categorie = p.categorie)
ORDER BY p.categorie, p.nom;

SELECT c.nom, (SELECT COUNT(*) FROM ventes AS v WHERE v.client_id = c.id) AS nb_achats
FROM clients AS c
ORDER BY nb_achats DESC, c.nom;
